// The FSR 3.1 upscaler's shader blob accessor (ADR 0060), in place of the SDK's
// sdk/src/backends/shared/blob_accessors/ffx_fsr3upscaler_shaderblobs.cpp, which includes
// headers generated by the SDK's shader compiler. The modules and their reflection come
// from examples/ffx_shaders.rs instead: the reflection and the permutation table in
// permutations_fsr3upscaler.inc, the SPIR-V from Rust (src/blobs.rs), handed over before
// the first context is created. Only the permutations the engine creates contexts for are
// there.

#include "ffx_engine.h"

#include <FidelityFX/host/ffx_util.h>
#include "ffx_fsr3upscaler_shaderblobs.h"
#include "fsr3upscaler/ffx_fsr3upscaler_private.h"

#include <cstring>

namespace {

#include "permutations_fsr3upscaler.inc"

// The shaders of examples/ffx_shaders.rs (`fsr3upscaler`'s `shaders`), and whether the
// SDK's accessor has 16-bit variants of them.
constexpr int32_t kNoShader = -1;
constexpr bool kHasFp16[] = {false, false, false, true, true, false, true, false, false, true};

int32_t shaderOf(FfxFsr3UpscalerPass pass)
{
    switch (pass)
    {
    case FFX_FSR3UPSCALER_PASS_PREPARE_INPUTS: return 0;
    case FFX_FSR3UPSCALER_PASS_LUMA_PYRAMID: return 1;
    case FFX_FSR3UPSCALER_PASS_SHADING_CHANGE_PYRAMID: return 2;
    case FFX_FSR3UPSCALER_PASS_SHADING_CHANGE: return 3;
    case FFX_FSR3UPSCALER_PASS_PREPARE_REACTIVITY: return 4;
    case FFX_FSR3UPSCALER_PASS_LUMA_INSTABILITY: return 5;
    case FFX_FSR3UPSCALER_PASS_ACCUMULATE:
    case FFX_FSR3UPSCALER_PASS_ACCUMULATE_SHARPEN: return 6;
    case FFX_FSR3UPSCALER_PASS_RCAS: return 7;
    case FFX_FSR3UPSCALER_PASS_DEBUG_VIEW: return 8;
    case FFX_FSR3UPSCALER_PASS_GENERATE_REACTIVE: return 9;
    default: return kNoShader;
    }
}

}  // namespace

FfxErrorCode fsr3UpscalerGetPermutationBlobByIndex(FfxFsr3UpscalerPass passId, uint32_t permutationOptions, FfxShaderBlob* outBlob)
{
    const int32_t shader = shaderOf(passId);
    if (shader == kNoShader)
    {
        std::memset(outBlob, 0, sizeof(FfxShaderBlob));
        return FFX_ERROR_INVALID_ARGUMENT;
    }
    const uint32_t fp16 = kHasFp16[shader] && FFX_CONTAINS_FLAG(permutationOptions, FSR3UPSCALER_SHADER_PERMUTATION_ALLOW_FP16) ? 1 : 0;
    // The option bits below FORCE_WAVE64: the defines of the permutation.
    const uint32_t options = permutationOptions & (FSR3UPSCALER_SHADER_PERMUTATION_FORCE_WAVE64 - 1);
    return engineFfxBlob(ENGINE_FFX_FSR3UPSCALER, g_permutations, sizeof(g_permutations) / sizeof(g_permutations[0]),
                         g_reflection, MODULE_COUNT, uint32_t(shader), fp16, options, outBlob);
}

FfxErrorCode fsr3UpscalerIsWave64(uint32_t permutationOptions, bool& isWave64)
{
    // The same module either way on Vulkan: the backend requests the subgroup size.
    isWave64 = FFX_CONTAINS_FLAG(permutationOptions, FSR3UPSCALER_SHADER_PERMUTATION_FORCE_WAVE64);
    return FFX_OK;
}
